const SURPRESA = {
  id: "surpresa",
  nome: "Surpresa",
  inspiracao: "O Mestre escolhe",
  resumo: "O Mestre sorteia um dos temas para vocês.",
  icone: "dado",
};

const DURACOES = [
  { id: "curta", nome: "Uma noite", resumo: "Aventura completa em cerca de 2 horas." },
  { id: "campanha", nome: "Campanha", resumo: "História longa, para vários encontros." },
];

/** Temperos de estrutura: um é sorteado junto com a semente, para variar a forma da história. */
const TEMPEROS = [
  "o vilão tem um motivo que o grupo vai conseguir entender",
  "um aliado do começo esconde algo importante",
  "o objetivo do primeiro ato é uma isca para algo maior",
  "o lugar do confronto final já aparece, disfarçado, no começo",
  "alguém importante precisa ser convencido, não derrotado",
  "vencer exige pagar um preço, e o grupo escolhe qual",
  "o perigo tem um prazo que corre desde a primeira cena",
  "um NPC aparentemente sem importância se torna decisivo no fim",
  "o grupo descobre que já esteve, sem saber, do lado errado",
  "dois vilões disputam a mesma coisa, e o grupo fica no meio",
];

const POR_ID = new Map(TEMAS.map((t) => [t.id, t]));
const sortear = (lista) => lista[crypto.randomInt(lista.length)];

/** O tema pelo id; id ausente ou desconhecido (mesas antigas) = clássico. */
function temaPorId(id) { return POR_ID.get(id) || POR_ID.get("classico"); }

/** Id de tema pedido pelo app → id gravado: "surpresa" sorteia; inválido ou ausente = "classico". */
function resolverTema(id) {
  if (id === "surpresa") return sortear(TEMAS).id;
  return POR_ID.has(id) ? id : "classico";
}

function duracaoValida(id) { return DURACOES.some((d) => d.id === id) ? id : "curta"; }
function ehTemaValido(id) { return id === "surpresa" || POR_ID.has(id); }
function ehDuracaoValida(id) { return DURACOES.some((d) => d.id === id); }

/** Lista para o app: só os campos públicos, com "surpresa" primeiro. */
function listaPublica() {
  return {
    temas: [SURPRESA, ...TEMAS].map(({ id, nome, inspiracao, resumo, icone }) => ({ id, nome, inspiracao, resumo, icone })),
    duracoes: DURACOES.map((d) => ({ ...d })),
  };
}

function sortearSemente(tema) { return sortear(temaPorId(tema?.id || tema).sementes); }
function sortearTempero() { return sortear(TEMPEROS); }

module.exports = {
  TEMAS, SURPRESA, DURACOES, TEMPEROS,
  temaPorId, resolverTema, duracaoValida, ehTemaValido, ehDuracaoValida, listaPublica, sortearSemente, sortearTempero,
};
